 manifest=json.load(open(p/'outcome.json'))
 manifest.update(title=title,status='ready_for_independent_review',outcome=('All coefficients are nonnegative for every natural exponent r, including the full bridge to the source formula.' if num==372794 else 'The source construction has at least 38 distinct prime outputs for inputs 677 and 401; both bounds 10 and 13 are false.'),novelty='Independent local formal verification of a known posted result; no new-discovery or first-formalization claim.',independent_review='Pending parent review; not counted as accepted by this lane.',formal_declarations=json.load(open(p/'build/audit.json'))['declarations'])
